const webhook = $input.first()?.json || {};
const body = webhook.body && typeof webhook.body === 'object' ? webhook.body : {};
const headers = Object.fromEntries(Object.entries(webhook.headers || {}).map(([key, value]) => [String(key).toLowerCase(), value]));
const expectedKey = String($env.JAVEDAI_WORKFLOW_KEY || '').trim();
const presentedKey = String(headers['x-javedai-key'] || '').trim();
const DRY_RUN = true;
function safeEqual(left, right) {
  if (!left || !right || left.length !== right.length) return false;
  let mismatch = 0;
  for (let index = 0; index < left.length; index += 1) mismatch |= left.charCodeAt(index) ^ right.charCodeAt(index);
  return mismatch === 0;
}
function clean(value, max = 300) { return String(value || '').replace(/[\u0000-\u001F\u007F]/g, ' ').replace(/\s+/g, ' ').trim().slice(0, max); }
function normalizeDomain(value) {
  const raw = clean(value, 300).toLowerCase();
  if (!raw) return '';
  try { return new URL(raw.includes('://') ? raw : 'https://' + raw).hostname.replace(/^www\./, ''); } catch { return ''; }
}
const responseEnvelope = body.response && typeof body.response === 'object' ? body.response : {};
const rawPeople = Array.isArray(body.people) ? body.people : Array.isArray(body.decision_makers) ? body.decision_makers : Array.isArray(responseEnvelope.decision_makers) ? responseEnvelope.decision_makers : Array.isArray(responseEnvelope.people) ? responseEnvelope.people : [body.person || body];
const seen = new Set();
const people = rawPeople.map((raw) => {
  const person = raw && typeof raw === 'object' ? raw : {};
  const firstName = clean(person.first_name, 80);
  const lastName = clean(person.last_name, 80);
  const fullName = clean(person.full_name || person.name || [firstName, lastName].filter(Boolean).join(' '), 180);
  const domain = normalizeDomain(person.domain || person.website || person.company_website);
  const suppressed = person.suppression_required === true || person.unsubscribed === true || person.do_not_contact === true;
  return { person_id: clean(person.person_id || person.id, 120), first_name: firstName, last_name: lastName, full_name: fullName, title: clean(person.title, 180), linkedin_url: clean(person.linkedin_url || person.profile_url, 400), company_id: clean(person.company_id, 120), company_name: clean(person.company_name || person.company, 180), domain, source: clean(person.source || 'decision_maker_discovery', 80), existing_email: clean(person.email, 254).toLowerCase(), suppression_required: suppressed };
}).filter((person) => {
  const key = person.person_id || person.linkedin_url || (person.full_name + '|' + person.domain).toLowerCase();
  if (!person.full_name || !person.domain || !key || seen.has(key)) return false;
  seen.add(key);
  person.dedupe_key = key;
  return true;
}).slice(0, 10);
const basisConfirmed = body.outreach_basis_confirmed === true || String(body.outreach_basis_confirmed || '').toLowerCase() === 'true';
const errors = [];
if (!expectedKey) errors.push('server_auth_not_configured');
if (!safeEqual(presentedKey, expectedKey)) errors.push('unauthorized');
if (!basisConfirmed) errors.push('outreach_basis_confirmation_required');
if (people.length === 0) errors.push('at_least_one_valid_person_and_domain_required');
return [{ json: { auth_valid: safeEqual(presentedKey, expectedKey), valid: errors.length === 0, errors, dry_run: DRY_RUN, request_id: clean(body.request_id, 120) || 'email-' + Date.now().toString(36), input_person_count: rawPeople.length, unique_person_count: people.length, people } }];

const finder = $input.first().json || {};
const person = $node['Loop Over People'].json;
const candidate = String(finder.email || person.existing_email || '').trim().toLowerCase();
const emailFound = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(candidate);
return [{ json: { ...person, email: candidate, email_found: emailFound, finder_status: String(finder.email_status || (emailFound ? 'candidate' : 'not_found')), email_source: finder.email ? 'anymail_finder' : person.existing_email ? 'input_fallback' : 'none', finder_credits_charged: Number(finder.credits_charged || 0) } }];

const verification = $input.first().json || {};
const person = $node['Parse Anymail Result'].json;
const status = String(verification.result || 'unknown').toLowerCase();
const flags = Array.isArray(verification.flags) ? verification.flags.map(String) : [];
const localPart = String(person.email || '').split('@')[0].toLowerCase();
const roleAccount = flags.includes('role_account') || /^(admin|billing|contact|hello|info|office|sales|support|team)$/.test(localPart);
let classification = 'risky';
let reason = status;
if (status === 'valid' && !roleAccount) classification = 'verified';
else if (status === 'invalid' || status === 'disposable') classification = 'rejected';
else if (status === 'valid' && roleAccount) reason = 'role_account';
const suppressed = person.suppression_required || classification === 'rejected';
return [{ json: { ...person, verification_status: status, verification_flags: flags, suggested_correction: String(verification.suggested_correction || ''), classification, classification_reason: reason, suppression_required: suppressed, outreach_allowed: classification === 'verified' && !suppressed, manual_review_required: classification === 'risky', verification_provider: 'neverbounce' } }];

const context = $node['Validate and Prepare People'].json;
const contacts = $input.all().map((item) => item.json).map((person) => {
  const classification = person.classification || 'rejected';
  const suppressed = Boolean(person.suppression_required);
  return { person_id: person.person_id || '', first_name: person.first_name || '', last_name: person.last_name || '', full_name: person.full_name || '', title: person.title || '', job_title: person.title || '', linkedin_url: person.linkedin_url || '', company_id: person.company_id || '', company_name: person.company_name || '', domain: person.domain || '', company_domain: person.domain || '', email: person.email || '', email_verified: classification === 'verified', email_source: person.email_source || 'none', finder_status: person.finder_status || 'not_run', verification_status: person.verification_status || 'not_run', verification_flags: person.verification_flags || [], classification, classification_reason: person.classification_reason || 'unclassified', suppression_required: suppressed, suppressed, outreach_allowed: Boolean(person.outreach_allowed), manual_review_required: Boolean(person.manual_review_required), source: person.source || 'decision_maker_discovery' };
});
const byEmail = new Set();
const deduped = contacts.filter((contact) => {
  const key = contact.email || (contact.full_name + '|' + contact.domain).toLowerCase();
  if (!key || byEmail.has(key)) return false;
  byEmail.add(key);
  return true;
});
return [{ json: { response: { ok: true, status: 'complete', dry_run: false, request_id: context.request_id, contact_count: deduped.length, verified_count: deduped.filter((contact) => contact.email_verified).length, risky_count: deduped.filter((contact) => contact.classification === 'risky').length, rejected_count: deduped.filter((contact) => contact.classification === 'rejected').length, outreach_allowed_count: deduped.filter((contact) => contact.outreach_allowed).length, contacts: deduped } } }];
